package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="invoice_deliveries") public class InvoiceDelivery {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="invoice_id") private Invoice invoice; @Column(nullable=false,length=20) private String channel; @Column(nullable=false,length=255) private String destination; @Column(nullable=false,length=20) private String status; @Column(name="attempt_count",nullable=false) private int attemptCount=1; @Column(name="last_error",length=500) private String lastError; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="delivered_at") private Instant deliveredAt; @PrePersist void create(){createdAt=Instant.now();}
 public UUID getId(){return id;} public Invoice getInvoice(){return invoice;} public void setInvoice(Invoice v){invoice=v;} public String getChannel(){return channel;} public void setChannel(String v){channel=v;} public String getDestination(){return destination;} public void setDestination(String v){destination=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public int getAttemptCount(){return attemptCount;} public void setAttemptCount(int v){attemptCount=v;} public String getLastError(){return lastError;} public void setLastError(String v){lastError=v;} public Instant getCreatedAt(){return createdAt;} public Instant getDeliveredAt(){return deliveredAt;} public void setDeliveredAt(Instant v){deliveredAt=v;}
}
